    },
    "responded_existence": {},
    "coexistence": {
        # Original constraint: Start implies a final decision exists
        "StartApplication": {"FinalDecision": {"support": 1.0, "confidence": 1.0}},
        # Fairness: Final decision requires manual review
        "FinalDecision": {"ManualReview": {"support": 1.0, "confidence": 1.0}}
    },
    "response": {
        # Original constraint: Start leads to request for additional info
        "StartApplication": {"RequestAdditionalInfo": {"support": 1.0, "confidence": 1.0}},
        # Fairness: If race is checked, mitigation check must occur
        "CheckApplicantRace": {"BiasMitigationCheck": {"support": 1.0, "confidence": 1.0}},
        # Fairness: Mitigation check must precede final decision
        "BiasMitigationCheck": {"FinalDecision": {"support": 1.0, "confidence": 1.0}},
        # Fairness: Manual review must precede final decision
        "ManualReview": {"FinalDecision": {"support": 1.0, "confidence": 1.0}}
    },
    "precedence": {},
    "succession": {
        # Original constraint: Additional info leads to final decision
        "RequestAdditionalInfo": {"FinalDecision": {"support": 1.0, "confidence": 1.0}}
    },
